dict.string:
.navbar {
font-family: 'Hoefler Text', 'Times New Roman', serif;
font-size: 1.1em;
color: #2D3D4C;
text-align: left;
}

.navbar-bg { 
background-image: url(baby_bk_3.jpg);
background-repeat: repeat-y;
}

.navbar ul {
list-style: none;
line-height: 30px;
margin: 0px;
padding: 0px 0 6px 50px;
}

.navbar ul li {
display: inline;
padding: 0px 35px 0px 0px;
}


.navbar a {
text-decoration: none;
color: #2D3D4C;
background-image: url(nav_normal_heart.png);
_background-image: url(nav_normal_heart.gif);
background-repeat: no-repeat;
background-position: 0px 3px;
padding: 5px 0 5px 25px;
}

.navbar a:visited {
text-decoration: none;
color: #2D3D4C;
background-image: url(nav_normal_heart.png);
_background-image: url(nav_normal_heart.gif);
background-repeat: no-repeat;
background-position: 0px 3px;
padding: 5px 0 5px 25px;
}

.noncurrent-page a:hover {
text-decoration: none;
color: #226CB2;
background-image: url(nav_rollover_heart.png);
_background-image: url(nav_rollover_heart.gif);
background-repeat: no-repeat;
background-position: 0px 3px;
padding: 5px 0 5px 25px;
}

.current-page a
{
text-decoration: none;
background-image: url(nav_active_heart.png);
_background-image: url(nav_active_heart.gif);
background-repeat: no-repeat;
background-position: 0px 3px;
padding: 5px 0 5px 25px;
color: #FFF;
}
